//! A dependency-free Rust port of the `sortedcontainers` C++ header.
//!
//! The containers keep their elements in ascending order using a two-level
//! list-of-lists layout: a `Vec` of bounded, sorted sublists plus a positional
//! index tree. Inserting or removing therefore shifts only a bounded number of
//! elements, while lookup by rank stays logarithmic.
//!
//! - [`SortedList`] -- a sorted sequence that keeps duplicates.
//! - [`SortedSet`] -- a sorted collection of unique values.
//! - [`SortedDict`] -- a map ordered by key.
//!
//! [`cstdlib`] holds the C `atoi` / `strtol` semantics the original program's
//! command-line parsing relied on.
//!
//! Only the standard library is used.

// The library exposes a full container API; a given binary uses part of it.
// The re-exports below are public API of the `lib` target, but appear unused
// when this file is pulled into a binary as a module.
#![allow(dead_code, unused_imports)]

// The `#[path]` attributes are relative to this file's own directory, so the
// modules resolve identically whether `lib.rs` is compiled as the crate root
// (`cargo build`) or pulled in as a module (`rustc test6.rs`).
#[path = "cstdlib.rs"]
pub mod cstdlib;
#[path = "sorted_dict.rs"]
pub mod sorted_dict;
#[path = "sorted_list.rs"]
pub mod sorted_list;
#[path = "sorted_set.rs"]
pub mod sorted_set;

pub use cstdlib::{c_atoi, c_strtol};
pub use sorted_dict::SortedDict;
pub use sorted_list::{SortedList, DEFAULT_LOAD_FACTOR};
pub use sorted_set::SortedSet;

//! Rust port of `tests/test6.cpp`.
//!
//! Builds two sorted sets -- `0..n` and the even numbers `0, 2, ..., 2n-2` --
//! unions them, then reports the three sizes followed by a membership check for
//! every value in `0..n`.
//!
//! The single optional argument is the count `n`, defaulting to 6, and is
//! parsed with C `atoi` semantics so that non-numeric input becomes 0 exactly
//! as it did in the original.

#[path = "src/lib.rs"]
mod sortedcontainers;

use std::io::{self, BufWriter, Write};

use sortedcontainers::{c_atoi, SortedSet};

fn main() {
    let argv: Vec<String> = std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();

    let mut n: i32 = 6;
    if argv.len() > 1 {
        n = c_atoi(&argv[1]);
    }

    let mut s1: SortedSet<i32> = SortedSet::new();
    let mut s2: SortedSet<i32> = SortedSet::new();
    let mut i: i32 = 0;
    while i < n {
        s1.insert(i);
        // Wrapping mirrors what the C++ `int` arithmetic does on overflow.
        s2.insert(i.wrapping_mul(2));
        i = i.wrapping_add(1);
    }

    let s3 = s1.union_with(&s2);

    // `std::cout` is line-buffered by `endl`; one buffered writer, flushed at
    // the end, produces the same bytes.
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());

    writeln!(out, "{}", s1.len()).expect("write to stdout");
    writeln!(out, "{}", s2.len()).expect("write to stdout");
    writeln!(out, "{}", s3.len()).expect("write to stdout");

    let mut i: i32 = 0;
    while i < n {
        // `std::cout` prints a bool as 1 or 0 without `boolalpha`.
        write!(out, "{} ", u8::from(s3.contains(&i))).expect("write to stdout");
        i = i.wrapping_add(1);
    }
    writeln!(out).expect("write to stdout");

    out.flush().expect("flush stdout");
}
